window.MG_LAZY_DATA["data/lazy/resources/security-v26-038-d33fbf8d722816a0.json"]={sha256:"d33fbf8d722816a05cea37b331c1db6b9a3761d54c47ed063fac60a14e97c491",value:{"sources":[{"id":"v26-case-1f1b26ebfa9e00d6","url":"https://attack.mitre.org/resources/","title":"MITRE ATT&CK: Get Started","titleEn":"MITRE ATT&CK: Get Started","publisher":"MITRE","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-038","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-038","related":[{"id":"security-v26-039","referenceUrls":["https://yara.readthedocs.io/en/stable/writingrules.html"],"title":"YARA：無害標記、字串條件與反例設計","titleEn":"YARA: inert markers, string conditions and negative fixtures","why":"用兩課的可觀察驗收條件比較模型邊界：60%與80%只對本地20假說成立；沒有攻擊真實目標，未受測項仍清楚可見。 交付20假說清單、正負例結果與可見範圍/盲點說明。","whyEn":"Compare model boundaries using observable acceptance criteria: Apply 60% and 80% only to the local 20 hypotheses; no real targets are attacked and untested items remain visible. Deliver 20 hypotheses, positive/negative results and visibility/uncertainty notes.","difference":"僅建立含ALPHA、BETA、GAMMA三個無害標記的文字fixture；對「至少兩個標記」列完整存在/不存在真值表，另外測空檔與文字編碼。","differenceEn":"Create text fixtures containing harmless ALPHA, BETA and GAMMA markers; enumerate presence/absence truth tables for at least two markers and separately test empty files and encoding.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["受測覆蓋率=已有正例與正常負例通過的假說/事先選定假說；不能將本地分母與完整ATT&CK技術總數混用。 教學範圍20個假說，其中12個完成正負例驗證，其餘8個未完成。 12/20×100=60%；補完4個後16/20×100=80%。","m個獨立布林標記有2^m種組合；存在性邏輯、字串邊界與編碼需分別驗證，樣本不可包含可執行惡意內容。 基準有3個標記，每個只計有/無，組合無其他限制。 2^3=8組；加入DELTA後2^4=16組。對至少兩標記條件，三標記版應有4組命中。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Tested coverage equals hypotheses passing positive and normal-negative fixtures divided by preselected hypotheses; do not mix the local denominator with the full ATT&CK catalog. The teaching scope contains 20 hypotheses, 12 validated with positive and negative fixtures and 8 unfinished. 12/20×100=60%; completing four more yields 16/20×100=80%.","m independent Boolean markers give 2^m combinations; test existence logic, word boundaries and encoding separately using no executable malicious content. Baseline has three markers, each present or absent with no other constraints. 2^3=8 combinations; adding DELTA gives 2^4=16. At least two of three should match four combinations.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-048","referenceUrls":["https://www.trustedcomputinggroup.org/resources/documents/tpm-library-specification"],"title":"TPM 2.0：PCR量測、Quote 與新鮮度","titleEn":"TPM 2.0: PCR measurements, quotes and freshness","why":"用兩課的可觀察驗收條件比較模型邊界：60%與80%只對本地20假說成立；沒有攻擊真實目標，未受測項仍清楚可見。 交付20假說清單、正負例結果與可見範圍/盲點說明。","whyEn":"Compare model boundaries using observable acceptance criteria: Apply 60% and 80% only to the local 20 hypotheses; no real targets are attacked and untested items remain visible. Deliver 20 hypotheses, positive/negative results and visibility/uncertainty notes.","difference":"用合成開機事件序列示範PCR延伸H(舊PCR||事件digest)；列出quote簽章、選取PCR、nonce及event log各自驗證責任。","differenceEn":"Use a synthetic boot-event sequence to illustrate PCR extension H(old PCR||event digest); separate quote signature, selected PCRs, nonce and event-log checks.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["受測覆蓋率=已有正例與正常負例通過的假說/事先選定假說；不能將本地分母與完整ATT&CK技術總數混用。 教學範圍20個假說，其中12個完成正負例驗證，其餘8個未完成。 12/20×100=60%；補完4個後16/20×100=80%。","若選取n個SHA-256 PCR值，原始digest資料量=32n位元組；不含簽章、選擇位圖與quote其他結構，量測不同不直接等於惡意。 教學挑選8個PCR，每個digest32位元組，僅計原始選取值。 8×32=256位元組；挑選12個後為384位元組。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Tested coverage equals hypotheses passing positive and normal-negative fixtures divided by preselected hypotheses; do not mix the local denominator with the full ATT&CK catalog. The teaching scope contains 20 hypotheses, 12 validated with positive and negative fixtures and 8 unfinished. 12/20×100=60%; completing four more yields 16/20×100=80%.","Selecting n SHA-256 PCR values yields 32n raw digest bytes, excluding signature, selection bitmap and other quote structures; differing measurements do not automatically imply malice. Select eight teaching PCRs with 32-byte digests and count only raw selected values. 8×32=256 bytes; selecting 12 gives 384 bytes.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-8b282b9c60ccf648","url":"https://yara.readthedocs.io/en/stable/writingrules.html","title":"YARA: Writing rules","titleEn":"YARA: Writing rules","publisher":"YARA Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-bb25785c3cf8abf7","url":"https://www.trustedcomputinggroup.org/resources/documents/tpm-library-specification","title":"TPM 2.0 Library specification","titleEn":"TPM 2.0 Library specification","publisher":"Trusted Computing Group","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
